<div class="page-actions"><div><p class="text-muted mb-0">Registra mascotas, informa extravíos y comparte su enlace QR.</p></div><button class="btn btn-primary" data-modal-open="petModal">+ Registrar mascota</button></div><div class="cards-grid"><?php if(!$pets):?><div class="card empty-state">Aún no hay mascotas registradas.</div><?php endif;?><?php foreach($pets as $pet):?><article class="pet-card"><div class="pet-photo"><span><?= e(mb_strtoupper(mb_substr($pet['name'],0,1))) ?></span><span class="badge pet-status status-<?= e($pet['status']) ?>"><?= e(str_replace('_',' ',$pet['status'])) ?></span></div><div class="pet-body"><h2><?= e($pet['name']) ?></h2><p><?= e($pet['species']) ?><?= $pet['breed']?' · '.e($pet['breed']):'' ?><?= $pet['color']?' · '.e($pet['color']):'' ?></p><small>Responsable: <?= e($pet['owner_name']) ?></small><?php if($pet['last_seen_address']):?><div class="last-seen">◎ <?= e($pet['last_seen_address']) ?></div><?php endif;?><div class="pet-actions"><a class="btn btn-outline-primary btn-sm" target="_blank" href="<?= url('mascota/qr/'.$pet['qr_token']) ?>">Ver perfil QR</a><form method="post" action="<?= url('mascotas/'.$pet['id'].'/estado') ?>"><?= csrf_field() ?><select class="form-select form-select-sm" name="status" onchange="this.form.submit()"><option value="en_casa" <?= $pet['status']==='en_casa'?'selected':'' ?>>En casa</option><option value="perdida" <?= $pet['status']==='perdida'?'selected':'' ?>>Perdida</option><option value="encontrada" <?= $pet['status']==='encontrada'?'selected':'' ?>>Encontrada</option></select></form></div></div></article><?php endforeach;?></div>
<div class="modal" id="petModal" hidden><div class="modal-dialog"><div class="modal-content"><div class="modal-header"><h2>Registrar mascota</h2><button data-modal-close>×</button></div><form method="post" action="<?= url('mascotas') ?>"><?= csrf_field() ?><div class="modal-body"><div class="row g-3"><div class="col-md-6"><label class="form-label">Nombre</label><input class="form-control" name="name" required></div><div class="col-md-6"><label class="form-label">Especie</label><select class="form-select" name="species" required><option>Perro</option><option>Gato</option><option>Ave</option><option>Otra</option></select></div><div class="col-md-6"><label class="form-label">Raza</label><input class="form-control" name="breed"></div><div class="col-md-6"><label class="form-label">Color</label><input class="form-control" name="color"></div><div class="col-12"><label class="form-label">Descripción y señas particulares</label><textarea class="form-control" name="description"></textarea></div><div class="col-md-6"><label class="form-label">Estado</label><select class="form-select" name="status"><option value="en_casa">En casa</option><option value="perdida">Perdida</option><option value="encontrada">Encontrada</option></select></div><div class="col-md-6"><label class="form-label">Último lugar visto</label><input class="form-control" name="last_seen_address"></div><div class="col-12"><label class="form-label">Fecha de extravío</label><input type="datetime-local" class="form-control" name="lost_at"></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-modal-close>Cancelar</button><button class="btn btn-primary">Guardar mascota</button></div></form></div></div></div>

